import time
import psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    start_time = time.time()

    while time.time() - start_time < interval_s:
        timestamp = time.time()
        for conn in psutil.net_connections(kind='inet'):
            if conn.status == 'ESTABLISHED' and conn.laddr.port == int(host.split(':')[-1]):
                logs.append({
                    "timestamp": timestamp,
                    "source": f"{conn.raddr.ip}:{conn.raddr.port}"
                })
        time.sleep(1)
    return logs
