from scapy.all import rdpcap, DNS, DNSQR
import base64
import re

def analyze_dns_traffic(pcap_file: str) -> dict:
    packets = rdpcap(pcap_file)
    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    subdomain_threshold = 4
    entropy_threshold = 4.0
    long_query_threshold = 50

    for pkt in packets:
        if pkt.haslayer(DNS) and pkt.haslayer(DNSQR):
            query = pkt[DNSQR].qname.decode().lower().rstrip('.')
            labels = query.split('.')

            # DGA Detection: High entropy and many subdomains
            if len(labels) > subdomain_threshold:
                if len(set(labels[0])) > 5: # Simple entropy proxy
                    suspicious["dga"].append(query)

            # Tunneling Detection: Long queries
            if len(query) > long_query_threshold:
                suspicious["tunneling"].append(query)

            # Exfiltration Detection: Base64-like patterns
            if re.match(r'^[a-zA-Z0-9+/=]{20,}$', labels[0]):
                try:
                    if len(labels[0]) % 4 == 0:
                        base64.b64decode(labels[0], validate=True)
                        suspicious["exfiltration"].append(query)
                except Exception:
                    pass

    return suspicious
